def read_publisher(rec):
    fields = (
        rec.get_fields('260')
        or rec.get_fields('264')[:1]
        or [rec.get_linkage('260', '880')]
    )
    if not fields:
        return
    publisher = []
    publish_places = []
    for f in fields:
        f.remove_brackets()
        contents = f.get_contents(['a', 'b'])
        if 'b' in contents:
            publisher += [x.strip(" /,;:") for x in contents['b']]
        if 'a' in contents:
            publish_places += [x.strip(" /.,;:") for x in contents['a'] if x]
    edition = {}
